	internal sealed class NQCRT_FamAcc
	{
		public int F, N, Count, RefCmp, RefBad; public long MaxUlp; public double MaxRel; public bool HasRef;
		public StringBuilder Bits = new StringBuilder(), Round = new StringBuilder();
		public string HashBits, HashRound;
		public List<string> Samples = new List<string>();                                                // "at:hexFeature" (16 por (familia,n))
		public StringBuilder Full = new StringBuilder();                                                 // filas completas f,n,p,at,hexF,hexD (solo familias trascendentes)
	}

	internal static class NQCRT_PerfRef
	{
		// Familias que usan funciones trascendentes (Exp, Log, Log10, Pow, Sin, Tanh) segun la auditoria DINAMICA del codigo (cada funcion sustituida por un contador; ver ET3.md): solo estas pueden diferir entre runtimes.
		public static readonly int[] TransFamilies = new int[] { 33, 44, 45, 46, 53, 68, 71, 85, 87, 88, 119 };
		public static string TransUse(int f)
		{
			switch (f) { case 33: return "Log"; case 44: return "Pow"; case 45: return "Exp+Log"; case 46: return "Pow"; case 53: return "Sin"; case 68: return "Tanh"; case 71: return "Log10"; case 85: return "Log"; case 87: return "Log"; case 88: return "Log"; case 119: return "Log"; }
			return "";
		}
		public static bool IsTrans(int f) { return Array.IndexOf(TransFamilies, f) >= 0; }
		public static readonly int[] RefFamilies = new int[] { 31, 44, 45, 54, 59, 69, 70, 92, 93 };
		public static bool HasRef(int f) { return Array.IndexOf(RefFamilies, f) >= 0; }

		public static string RuntimeName() { return Type.GetType("Mono.Runtime") != null ? "mono" : "net"; }
		public static string RuntimeInfo()
		{
			string fw = ""; try { Type t = Type.GetType("System.Runtime.InteropServices.RuntimeInformation"); if (t != null) fw = (string)t.GetProperty("FrameworkDescription").GetValue(null, null); } catch { }
			return RuntimeName() + " | CLR " + Environment.Version.ToString() + " | " + fw + " | " + (IntPtr.Size * 8).ToString(CultureInfo.InvariantCulture) + " bits | " + Environment.OSVersion.ToString();
		}

		// ---- ulps y error relativo
		public static bool Same(double a, double b)
		{
			if (double.IsNaN(a) && double.IsNaN(b)) return true;
			return BitConverter.DoubleToInt64Bits(a) == BitConverter.DoubleToInt64Bits(b);
		}
		private static long Ord(double x) { long b = BitConverter.DoubleToInt64Bits(x); return b < 0 ? long.MinValue - b : b; }
		public static long Ulps(double a, double b)
		{
			bool na = double.IsNaN(a), nb = double.IsNaN(b); if (na && nb) return 0; if (na || nb) return long.MaxValue;
			if (a == b) return 0; if (double.IsInfinity(a) || double.IsInfinity(b)) return long.MaxValue;
			long d = unchecked(Ord(a) - Ord(b)); if (d < 0) d = d == long.MinValue ? long.MaxValue : -d; return d;
		}
		public static double Rel(double a, double b)
		{
			if (double.IsNaN(a) || double.IsNaN(b) || double.IsInfinity(a) || double.IsInfinity(b)) return Same(a, b) ? 0 : double.PositiveInfinity;
			double m = Math.Max(Math.Abs(a), Math.Abs(b)); return m == 0 ? 0 : Math.Abs(a - b) / m;
		}
		private static string Hx(double x) { return BitConverter.DoubleToInt64Bits(x).ToString("x16", CultureInfo.InvariantCulture); }
		private static string Rd(double x) { return (double.IsNaN(x) || double.IsInfinity(x)) ? "NaN" : x.ToString("E11", CultureInfo.InvariantCulture); }   // 12 cifras significativas
		private static double Clean(double x) { return (double.IsNaN(x) || double.IsInfinity(x)) ? double.NaN : x; }

		// ---- COPIA CONGELADA de las formulas del commit 4006522 (antes de optimizar) de las familias tocadas. NO usa sumas prefijo, ni memo auxiliar, ni memo MACD, ni la lectura directa de P().
		private static double MacdRef(NQCE3_Series sr, int fast, int slow, int at) { return NQCE3_M.EMA(sr, at, fast) - NQCE3_M.EMA(sr, at, slow); }
		private static double HighestRef(NQCE3_Series sr, int at, int n, int kind) { double x = Double.NegativeInfinity; for (int k = at - n + 1; k <= at; k++) x = Math.Max(x, NQCE3_M.PRef(sr, k, kind)); return x; }
		private static double LowestRef(NQCE3_Series sr, int at, int n, int kind) { double x = Double.PositiveInfinity; for (int k = at - n + 1; k <= at; k++) x = Math.Min(x, NQCE3_M.PRef(sr, k, kind)); return x; }
		private static double RsiRef(NQCE3_Series sr, int at, int n)
		{
			double gain = 0, loss = 0;
			for (int k = at - n + 1; k <= at; k++) { double diff = NQCE3_M.PRef(sr, k, 0) - NQCE3_M.PRef(sr, k - 1, 0); gain += Math.Max(0, diff); loss += Math.Max(0, -diff); }
			return NQCE3_M.Div(gain - loss, gain + loss);
		}
		private static double FamRef(NQCE3_Series sr, int f, int n, int at)
		{
			double p = sr.C[at], atr = sr.AtrAt(at); int half = Math.Max(2, n / 2), start = at - n + 1;
			switch (f)
			{
				case 31:
				{
					double signal = 0, a = 2.0 / (n + 1); int startIdx = at - n + 1;
					for (int k = startIdx; k <= at; k++) { double macd = MacdRef(sr, n, 2 * n, k); if (k == startIdx) signal = macd; else signal += a * (macd - signal); }
					double last = MacdRef(sr, n, 2 * n, at);
					return (last - signal) / atr;
				}
				case 44:
				{
					int startIdx = at - 2 * n; double kama = sr.C[startIdx];
					for (int k = startIdx + 1; k <= at; k++)
					{
						int t = Math.Max(startIdx, k - n), diffs = 0; double travel = 0;
						for (int j = t + 1; j <= k; j++) { travel += Math.Abs(sr.C[j] - sr.C[j - 1]); diffs++; }
						double er = diffs == 0 ? 0 : Math.Abs(NQCE3_M.Div(sr.C[k] - sr.C[t], travel));
						double a = Math.Pow(er * (2.0 / 3 - 2.0 / 31) + 2.0 / 31, 2); kama += a * (sr.C[k] - kama);
					}
					return (p - kama) / atr;
				}
				case 45:
				{
					double frama = sr.C[at - 2 * n]; int h = Math.Max(2, n / 2);
					for (int k = at - 2 * n + 1; k <= at; k++)
					{
						if (k < n) continue;
						double hi1 = HighestRef(sr, k, h, 2), lo1 = LowestRef(sr, k, h, 3), hi2 = HighestRef(sr, k - h, h, 2), lo2 = LowestRef(sr, k - h, h, 3), hi = HighestRef(sr, k, 2 * h, 2), lo = LowestRef(sr, k, 2 * h, 3);
						double d1 = (hi1 - lo1) / h, d2 = (hi2 - lo2) / h, d3 = (hi - lo) / (2.0 * h);
						double dimension = d1 + d2 <= NQCE3_M.Eps || d3 <= NQCE3_M.Eps ? 1 : Math.Log((d1 + d2) / d3) / Math.Log(2);
						double alpha = NQCE3_M.Clip(Math.Exp(-4.6 * (dimension - 1)), 0.01, 1);
						frama += alpha * (sr.C[k] - frama);
					}
					return (p - frama) / atr;
				}
				case 54:
				{
					double vidya = sr.C[at - 2 * n];
					for (int k = at - 2 * n + 1; k <= at; k++)
					{
						int look = Math.Min(n, k - (at - 2 * n)); double gain = 0, loss = 0;
						for (int j = k - look + 1; j <= k; j++) { double d = sr.C[j] - sr.C[j - 1]; gain += Math.Max(0, d); loss += Math.Max(0, -d); }
						double cmo = Math.Abs(NQCE3_M.Div(gain - loss, gain + loss)); vidya += 2.0 / (n + 1) * cmo * (sr.C[k] - vidya);
					}
					return (p - vidya) / atr;
				}
				case 59:
				{
					double lo = Double.PositiveInfinity, hi = Double.NegativeInfinity;
					for (int k = start; k <= at; k++) { double x = RsiRef(sr, k, n); lo = Math.Min(lo, x); hi = Math.Max(hi, x); }
					return NQCE3_M.Div(2 * RsiRef(sr, at, n) - hi - lo, hi - lo);
				}
				case 69:
				{
					int fast = Math.Max(2, n / 2), slow = Math.Max(3, 2 * n);
					double lo = Double.PositiveInfinity, hi = Double.NegativeInfinity;
					for (int k = start; k <= at; k++) { double m = MacdRef(sr, fast, slow, k); lo = Math.Min(lo, m); hi = Math.Max(hi, m); }
					double stoch = NQCE3_M.Div(MacdRef(sr, fast, slow, at) - lo, hi - lo); double mean = 0;
					for (int k = start; k <= at; k++)
					{
						double min = Double.PositiveInfinity, max = Double.NegativeInfinity;
						for (int j = Math.Max(start, k - half + 1); j <= k; j++) { double v = MacdRef(sr, fast, slow, j); min = Math.Min(min, v); max = Math.Max(max, v); }
						mean += NQCE3_M.Div(MacdRef(sr, fast, slow, k) - min, max - min);
					}
					return 2 * (0.5 * stoch + 0.5 * mean / n) - 1;
				}
				case 70:
				{
					int startIdx = at - n + 1; double alpha = 2.0 / (Math.Max(2, n / 2) + 1), d = 0, d2 = 0;
					for (int k = startIdx; k <= at; k++)
					{
						int look = Math.Min(n, k + 1); double hi = HighestRef(sr, k, look, 2), lo = LowestRef(sr, k, look, 3); double x = sr.C[k] - (hi + lo) / 2;
						if (k == startIdx) { d = x; d2 = d; } else { d += alpha * (x - d); d2 += alpha * (d - d2); }
					}
					return d2 / atr;
				}
				case 92:
				{
					double trend = NQCE3_M.Div(p - sr.C[at - n], n * atr); double ulcer = 0;
					for (int k = start; k <= at; k++) { double hi = HighestRef(sr, k, Math.Min(n, k + 1), 0); double dd = NQCE3_M.Div(sr.C[k] - hi, atr); ulcer += dd * dd; }
					return NQCE3_M.Div(trend, Math.Max(Math.Sqrt(ulcer / n), NQCE3_M.Eps));
				}
				case 93:
				{
					double longStop = Double.NegativeInfinity, shortStop = Double.PositiveInfinity;
					for (int k = at - half + 1; k <= at; k++)
					{
						double a = sr.AtrAt(k);
						longStop = Math.Max(longStop, HighestRef(sr, k, n, 2) - 2 * a); shortStop = Math.Min(shortStop, LowestRef(sr, k, n, 3) + 2 * a);
					}
					if (p > longStop) return (p - longStop) / atr; if (p < shortStop) return (p - shortStop) / atr; return 0;
				}
			}
			throw new ArgumentOutOfRangeException("f");
		}
		// Ruta de REFERENCIA del numerador (Direct): familias tocadas con la formula congelada; el resto con el calculo directo de produccion (sin cache).
		public static double RefDirect(NQCE3_Series s, int f, int n, int p, int at, bool unit)
		{
			if (!HasRef(f)) return s.Direct(f, n, p, at, unit);
			s.SetAtr(p, unit);
			try { return FamRef(s, f, n, at); } finally { s.SetAtr(p, true); }
		}
		// Ruta de REFERENCIA del valor de familia (equivale a Feature sin cache): misma descomposicion D-031(3) que el commit anterior.
		public static double RefFeature(NQCE3_Series s, int f, int n, int p, int at)
		{
			char kd = NQCE3_Catalog.AtrKindOf(f);
			if (kd == '2') return Clean(RefDirect(s, f, n, p, at, false));
			double v = Clean(RefDirect(s, f, n, p, at, true));
			if (kd == '1' && !double.IsNaN(v)) v = Clean(v / Math.Max(s.Src.Atr(p)[at], NQCE3_Series.AtrEps));
			return v;
		}

		// ---- barrido: MISMA muestra y MISMO orden que la huella del commit 4006522 (la huella global fd es la misma definicion)
		public static List<NQCRT_FamAcc> Scan(NQCE3_Series s, NQCE_Bars bars, int stride, out int count, out string fullHash)
		{
			List<int> win = new List<int>(); for (int i = 0; i < bars.Count; i++) if (bars.Stamp[i] >= 567 && bars.Stamp[i] <= 692 && bars.DayKey[i] >= 20200301) win.Add(i);
			List<int> sample = new List<int>(); for (int k = 0; k < win.Count; k += stride) sample.Add(win[k]);
			for (int i = 0; i < bars.Count && sample.Count < 400; i++) if (bars.Stamp[i] == 569 || bars.Stamp[i] == 570) if (bars.DayKey[i] >= 20200301 && (i % 7) == 0) sample.Add(i);
			int[] ns = new int[] { 4, 5, 9, 13, 17, 22, 26, 30 }; int[] ps = new int[] { 5, 14, 37, 100 };
			List<NQCRT_FamAcc> res = new List<NQCRT_FamAcc>(); count = 0; StringBuilder all = new StringBuilder();
			for (int f = 0; f < NQCE3_Catalog.Families; f++)
			{
				if (!NQCE3_Catalog.IsActiveFamily(f)) continue; char kd = NQCE3_Catalog.AtrKindOf(f); bool tr = IsTrans(f);
				foreach (int n in ns)
				{
					NQCRT_FamAcc a = new NQCRT_FamAcc(); a.F = f; a.N = n; a.HasRef = HasRef(f); List<double[]> rows14 = new List<double[]>();
					foreach (int p in ps)
					{
						if (kd != '2' && p != 14 && p != 100) continue;
						foreach (int at in sample)
						{
							if (at - (7 * n + 10) < 0) continue;
							double v1 = s.Feature(f, n, p, at), v2 = s.Direct(f, n, p, at, kd != '2');
							a.Bits.Append(f).Append(',').Append(n).Append(',').Append(p).Append(',').Append(at).Append(',').Append(Hx(v1)).Append(',').Append(Hx(v2)).Append('\n'); a.Count++;
							a.Round.Append(f).Append(',').Append(n).Append(',').Append(p).Append(',').Append(at).Append(',').Append(Rd(v1)).Append(',').Append(Rd(v2)).Append('\n');
							if (tr) a.Full.Append(f).Append('\t').Append(n).Append('\t').Append(p).Append('\t').Append(at).Append('\t').Append(Hx(v1)).Append('\t').Append(Hx(v2)).Append('\n');
							if (p == 14) rows14.Add(new double[] { at, v1 });
							// ruta de referencia (formula congelada del commit 4006522 o calculo directo) EN ESTE MISMO runtime
							double r1 = RefFeature(s, f, n, p, at), r2 = RefDirect(s, f, n, p, at, kd != '2');
							a.RefCmp += 2; long u1 = Ulps(v1, r1), u2 = Ulps(v2, r2);
							if (u1 != 0) { a.RefBad++; a.MaxUlp = Math.Max(a.MaxUlp, u1); a.MaxRel = Math.Max(a.MaxRel, Rel(v1, r1)); }
							if (u2 != 0) { a.RefBad++; a.MaxUlp = Math.Max(a.MaxUlp, u2); a.MaxRel = Math.Max(a.MaxRel, Rel(v2, r2)); }
						}
					}
					int step = Math.Max(1, rows14.Count / 16);
					for (int j = 0; j < rows14.Count && a.Samples.Count < 16; j += step) a.Samples.Add(((int)rows14[j][0]).ToString(CultureInfo.InvariantCulture) + ":" + Hx(rows14[j][1]));
					string bt = a.Bits.ToString(); a.HashBits = NQCE_Const.Sha256Text(bt); a.HashRound = NQCE_Const.Sha256Text(a.Round.ToString()); all.Append(bt); count += a.Count;
					a.Bits = null; a.Round = null; res.Add(a);
				}
			}
			fullHash = NQCE_Const.Sha256Text(all.ToString()); return res;
		}

		// ---- constantes por runtime: "f:n:hash8" separadas por espacio (huella exacta de la (familia,n)) y "f:n|at:hex,at:hex,..." (muestra de valores de las familias trascendentes)
		public static string GoldHashText(List<NQCRT_FamAcc> accs)
		{
			StringBuilder sb = new StringBuilder(); foreach (NQCRT_FamAcc a in accs) sb.Append(a.F).Append(':').Append(a.N).Append(':').Append(a.HashBits.Substring(0, 8)).Append(' '); return sb.ToString().TrimEnd();
		}
		public static string GoldValsText(List<NQCRT_FamAcc> accs)
		{
			StringBuilder sb = new StringBuilder();
			foreach (NQCRT_FamAcc a in accs) if (IsTrans(a.F)) { sb.Append(a.F).Append(':').Append(a.N).Append('|').Append(string.Join(",", a.Samples.ToArray())).Append(' '); }
			return sb.ToString().TrimEnd();
		}
		private static Dictionary<string, string> ParseKV(string text, char sep2)
		{
			Dictionary<string, string> d = new Dictionary<string, string>(); if (string.IsNullOrEmpty(text)) return d;
			foreach (string t in text.Split(new char[] { ' ' }, StringSplitOptions.RemoveEmptyEntries)) { int i = t.LastIndexOf(sep2); if (i > 0) d[t.Substring(0, i)] = t.Substring(i + 1); }
			return d;
		}

		public sealed class CrossResult { public bool Ok = true; public int FamDiff, FamExpected, FamBad; public long MaxUlpSample; public string Text = ""; public List<string> Rows = new List<string>(); }
		// Compara los valores de ESTE runtime con la constante dorada de otro (o del mismo) runtime. exact=true: toda diferencia es FALLA. exact=false: solo se aceptan diferencias en familias trascendentes con <= maxUlp ulps
		// (medidos en la muestra de 16 valores por (familia,n)); cualquier otra diferencia es FALLA.
		public static CrossResult Compare(List<NQCRT_FamAcc> accs, string goldHash, string goldVals, bool exact, long maxUlp)
		{
			CrossResult cr = new CrossResult(); Dictionary<string, string> gh = ParseKV(goldHash, ':'), gv = ParseKV(goldVals, '|');
			Dictionary<int, long> famUlp = new Dictionary<int, long>(); Dictionary<int, int> famDiffN = new Dictionary<int, int>(); Dictionary<int, bool> famNoVals = new Dictionary<int, bool>();
			foreach (NQCRT_FamAcc a in accs)
			{
				string key = a.F.ToString(CultureInfo.InvariantCulture) + ":" + a.N.ToString(CultureInfo.InvariantCulture); string g;
				if (!gh.TryGetValue(key, out g)) continue; if (g == a.HashBits.Substring(0, 8)) continue;
				int c; famDiffN.TryGetValue(a.F, out c); famDiffN[a.F] = c + 1;
				long mu; famUlp.TryGetValue(a.F, out mu);
				string gvals; if (gv.TryGetValue(key, out gvals))
				{
					Dictionary<string, string> cur = new Dictionary<string, string>(); foreach (string sm in a.Samples) { int i = sm.IndexOf(':'); cur[sm.Substring(0, i)] = sm.Substring(i + 1); }
					foreach (string t in gvals.Split(new char[] { ',' }, StringSplitOptions.RemoveEmptyEntries))
					{
						int i = t.IndexOf(':'); string at = t.Substring(0, i), hx = t.Substring(i + 1), now; if (!cur.TryGetValue(at, out now)) continue;
						double x = BitConverter.Int64BitsToDouble(Convert.ToInt64(hx, 16)), y = BitConverter.Int64BitsToDouble(Convert.ToInt64(now, 16)); mu = Math.Max(mu, Ulps(x, y));
					}
				}
				else famNoVals[a.F] = true;
				famUlp[a.F] = mu;
			}
			foreach (KeyValuePair<int, int> kv in famDiffN)
			{
				int f = kv.Key; bool tr = IsTrans(f); long u = famUlp.ContainsKey(f) ? famUlp[f] : 0; bool noVals = famNoVals.ContainsKey(f); cr.FamDiff++; cr.MaxUlpSample = Math.Max(cr.MaxUlpSample, u);
				bool expected = !exact && tr && !noVals && u <= maxUlp; if (expected) cr.FamExpected++; else { cr.FamBad++; cr.Ok = false; }
				cr.Rows.Add(f.ToString(CultureInfo.InvariantCulture) + "\t" + NQCE3_Catalog.FamilyNames[f] + "\t" + (tr ? TransUse(f) : "(sin trascendentes)") + "\t" + kv.Value.ToString(CultureInfo.InvariantCulture) + "\t" + (u == long.MaxValue ? "NaN/inf" : u.ToString(CultureInfo.InvariantCulture)) + "\t" + (expected ? "ESPERADA" : "FALLA"));
			}
			cr.Text = "familias que difieren=" + cr.FamDiff.ToString(CultureInfo.InvariantCulture) + " (esperadas " + cr.FamExpected.ToString(CultureInfo.InvariantCulture) + ", inesperadas " + cr.FamBad.ToString(CultureInfo.InvariantCulture) + ") max_ulps_en_muestra=" + (cr.MaxUlpSample == long.MaxValue ? "NaN/inf" : cr.MaxUlpSample.ToString(CultureInfo.InvariantCulture));
			return cr;
		}

		// ---- huella de la libm del runtime: funciones trascendentes sobre argumentos deterministas (independiente de la biblioteca de familias)
		public static void LibmTable(StringBuilder values, StringBuilder summary)
		{
			string[] names = new string[] { "Exp", "Log", "Log10", "Pow2", "Pow4", "Sin", "Tanh" }; ulong seed = 0x9E3779B97F4A7C15UL;
			double[] xs = new double[2000]; for (int i = 0; i < xs.Length; i++) { seed = unchecked(seed * 6364136223846793005UL + 1442695040888963407UL); xs[i] = ((seed >> 11) / 9007199254740992.0); }
			for (int q = 0; q < names.Length; q++)
			{
				StringBuilder sb = new StringBuilder();
				for (int i = 0; i < xs.Length; i++)
				{
					double x = xs[i], y;
					switch (q) { case 0: y = Math.Exp(-8 * x); break; case 1: y = Math.Log(0.05 + 20 * x); break; case 2: y = Math.Log10(0.05 + 20 * x); break; case 3: y = Math.Pow(0.05 + x, 2); break; case 4: y = Math.Pow(0.05 + x, 4); break; case 5: y = Math.Sin(Math.PI * (1 + 30 * x) / 31); break; default: y = Math.Tanh(5 * x - 2.5); break; }
					string h = Hx(y); sb.Append(h).Append('\n'); if (values != null) values.Append(names[q]).Append('\t').Append(i).Append('\t').Append(h).Append('\n');
				}
				summary.Append(names[q]).Append('\t').Append(xs.Length).Append('\t').Append(NQCE_Const.Sha256Text(sb.ToString()).Substring(0, 16)).Append('\n');
			}
		}

		// ---- cuadro de diagnostico por (familia,n) y por familia
		public static string FamTsv(List<NQCRT_FamAcc> accs)
		{
			StringBuilder sb = new StringBuilder(); sb.Append("familia\tnombre\tn\ttrascendentes\tformula_congelada\tvalores\thuella_bits\thuella_red12\tref_comparaciones\tref_difieren\tref_max_ulps\tref_max_rel\n");
			Dictionary<int, StringBuilder> fb = new Dictionary<int, StringBuilder>(), fr = new Dictionary<int, StringBuilder>(); Dictionary<int, long[]> fs = new Dictionary<int, long[]>(); Dictionary<int, double> fm = new Dictionary<int, double>();
			foreach (NQCRT_FamAcc a in accs)
			{
				sb.Append(a.F).Append('\t').Append(NQCE3_Catalog.FamilyNames[a.F]).Append('\t').Append(a.N).Append('\t').Append(IsTrans(a.F) ? TransUse(a.F) : "-").Append('\t').Append(a.HasRef ? "SI" : "no").Append('\t').Append(a.Count).Append('\t').Append(a.HashBits.Substring(0, 16)).Append('\t').Append(a.HashRound.Substring(0, 16)).Append('\t').Append(a.RefCmp).Append('\t').Append(a.RefBad).Append('\t').Append(a.MaxUlp == long.MaxValue ? "NaN/inf" : a.MaxUlp.ToString(CultureInfo.InvariantCulture)).Append('\t').Append(a.MaxRel.ToString("E3", CultureInfo.InvariantCulture)).Append('\n');
				if (!fb.ContainsKey(a.F)) { fb[a.F] = new StringBuilder(); fr[a.F] = new StringBuilder(); fs[a.F] = new long[3]; fm[a.F] = 0; }
				fb[a.F].Append(a.HashBits); fr[a.F].Append(a.HashRound); long[] z = fs[a.F]; z[0] += a.Count; z[1] += a.RefBad; z[2] = Math.Max(z[2], a.MaxUlp); fm[a.F] = Math.Max(fm[a.F], a.MaxRel);
			}
			foreach (KeyValuePair<int, StringBuilder> kv in fb)
			{
				int f = kv.Key; long[] z = fs[f];
				sb.Append(f).Append('\t').Append(NQCE3_Catalog.FamilyNames[f]).Append("\tTODOS\t").Append(IsTrans(f) ? TransUse(f) : "-").Append('\t').Append(HasRef(f) ? "SI" : "no").Append('\t').Append(z[0]).Append('\t').Append(NQCE_Const.Sha256Text(kv.Value.ToString()).Substring(0, 16)).Append('\t').Append(NQCE_Const.Sha256Text(fr[f].ToString()).Substring(0, 16)).Append("\t-\t").Append(z[1]).Append('\t').Append(z[2] == long.MaxValue ? "NaN/inf" : z[2].ToString(CultureInfo.InvariantCulture)).Append('\t').Append(fm[f].ToString("E3", CultureInfo.InvariantCulture)).Append('\n');
			}
			return sb.ToString();
		}
		public static string SampleTsv(List<NQCRT_FamAcc> accs)
		{
			StringBuilder sb = new StringBuilder(); sb.Append("familia\tn\tat\tvalor_feature_hex\n");
			foreach (NQCRT_FamAcc a in accs) foreach (string sm in a.Samples) { int i = sm.IndexOf(':'); sb.Append(a.F).Append('\t').Append(a.N).Append('\t').Append(sm.Substring(0, i)).Append('\t').Append(sm.Substring(i + 1)).Append('\n'); }
			return sb.ToString();
		}
	}

	// ============================================================================================================================================================
	// NQC_RUN_PerfDiag - MODO DE DIAGNOSTICO RAPIDO (minutos): huellas por familia en el runtime de NT8 y escritura de DIAG_PERF_FAMILIAS.tsv (+ valores y libm) para compararlas con otro runtime.
	// SIN ordenes, SOLO barras sinteticas. Requiere los mismos archivos que NQC_RUN_PerfTest. No calcula resultados de mercado.
	// ============================================================================================================================================================
	public class NQC_RUN_PerfDiag : Strategy
	{
		private const string ScriptVersion = "RUNPERFDIAG-1.0.0";
		private bool started, done; public string SummaryText = "";
		protected override void OnStateChange()
		{
			if (State == State.SetDefaults) { Description = "Diagnostico rapido de huellas de familias por runtime (sin ordenes)."; Name = "NQC_RUN_PerfDiag"; Calculate = Calculate.OnBarClose; BarsRequiredToTrade = 0; IsExitOnSessionCloseStrategy = false; }
			else if (State == State.DataLoaded) started = true;
			else if (State == State.Terminated)
			{
				if (!started || done) return; done = true;
				try { RunDiag(); }
				catch (Exception ex)
				{
					Print("NQC_PERFDIAG_ERROR " + ex.Message + " | " + ex.StackTrace);
					try { string d = Path.Combine(NinjaTrader.Core.Globals.UserDataDir, "NQC_Results"); Directory.CreateDirectory(d); File.WriteAllText(Path.Combine(d, "PERFDIAG_ERROR_" + DateTime.Now.ToString("yyyyMMdd_HHmmss", CultureInfo.InvariantCulture) + ".txt"), ex.ToString()); } catch { }
				}
			}
		}
		protected override void OnBarUpdate() { }
		public void RunDiag()
		{
			Stopwatch sw = Stopwatch.StartNew(); NQCE3_Series.MemoBudgetBytes = 1024L * 1024 * 1024;
			double[] vol; NQCE_Bars bars = NQCE3_SynthM1.Make(120, 777L, out vol); NQCE3_Library lib = new NQCE3_Library(); NQCE3_Fitness fit = new NQCE3_Fitness(bars, vol, new NQCE_Config(), lib);
			NQCE3_Series s = lib.SeriesFor(bars); int cnt; string fd; List<NQCRT_FamAcc> accs = NQCRT_PerfRef.Scan(s, bars, 211, out cnt, out fd);
			StringBuilder libmV = new StringBuilder(), libmS = new StringBuilder(); libmV.Append("funcion\ti\tbits\n"); libmS.Append("funcion\targumentos\thuella\n"); NQCRT_PerfRef.LibmTable(libmV, libmS);
			long refBad = 0, refCmp = 0, maxUlp = 0; int famRef = 0; foreach (NQCRT_FamAcc a in accs) { refBad += a.RefBad; refCmp += a.RefCmp; maxUlp = Math.Max(maxUlp, a.MaxUlp); if (a.HasRef && a.N == 4) famRef++; }
			string gh = NQCRT_PerfRef.GoldHashText(accs), gv = NQCRT_PerfRef.GoldValsText(accs);
			StringBuilder full = new StringBuilder(); full.Append("familia\tn\tp\tat\tfeature_hex\tdirect_hex\n"); foreach (NQCRT_FamAcc a in accs) full.Append(a.Full.ToString());
			string root = Path.Combine(NinjaTrader.Core.Globals.UserDataDir, "NQC_Results", "RUNPERF_DIAG_" + DateTime.Now.ToString("yyyyMMdd_HHmmss", CultureInfo.InvariantCulture)); Directory.CreateDirectory(root);
			UTF8Encoding u8 = new UTF8Encoding(false);
			File.WriteAllText(Path.Combine(root, "DIAG_PERF_FAMILIAS.tsv"), NQCRT_PerfRef.FamTsv(accs), u8);
			File.WriteAllText(Path.Combine(root, "DIAG_PERF_VALORES.tsv"), NQCRT_PerfRef.SampleTsv(accs), u8);
			File.WriteAllText(Path.Combine(root, "DIAG_PERF_TRANS_COMPLETO.tsv"), full.ToString(), u8);
			File.WriteAllText(Path.Combine(root, "DIAG_PERF_LIBM.tsv"), libmV.ToString(), u8);
			File.WriteAllText(Path.Combine(root, "DIAG_PERF_GOLD.txt"), "runtime=" + NQCRT_PerfRef.RuntimeName() + "\nfull_hash=" + fd + "\ngold_hash=" + gh + "\ngold_vals=" + gv + "\n", u8);
			StringBuilder su = new StringBuilder();
			su.Append("NQC RUN PERF DIAG - SUMMARY\nscript_version : " + ScriptVersion + "\nlibrary        : " + lib.Version + "\nruntime        : " + NQCRT_PerfRef.RuntimeInfo() + "\n");
			su.Append("valores        : " + cnt.ToString(CultureInfo.InvariantCulture) + "\nhuella_global  : " + fd + "\n");
			su.Append("ref_comparaciones : " + refCmp.ToString(CultureInfo.InvariantCulture) + "\nref_difieren      : " + refBad.ToString(CultureInfo.InvariantCulture) + "\nref_max_ulps      : " + maxUlp.ToString(CultureInfo.InvariantCulture) + "\nfamilias_con_formula_congelada : " + famRef.ToString(CultureInfo.InvariantCulture) + "\n");
			su.Append("libm (funcion, argumentos, huella):\n" + libmS.ToString());
			su.Append("segundos        : " + sw.Elapsed.TotalSeconds.ToString("0.0", CultureInfo.InvariantCulture) + "\nresult         : " + (refBad == 0 ? "PASS (ruta optimizada == referencia, bit a bit, en este runtime)" : "FAIL (la optimizacion cambia valores)") + "\nsalida         : " + root + "\n");
			File.WriteAllText(Path.Combine(root, "SUMMARY.txt"), su.ToString(), u8); SummaryText = su.ToString(); Print(su.ToString());
			NQCE3_Series.MemoBudgetBytes = 256L * 1024 * 1024;
		}
	}
}
